WITH ranked_events AS (SELECT e.event_id, e.account_id, e.event_type, e.tags, e.score, e.quality, e.metadata, row_number() OVER (PARTITION BY e.account_id ORDER BY e.event_time DESC, e.event_id DESC) AS rn FROM query_dump_events e WHERE e.event_type IN ('purchase', 'refund') AND e.score BETWEEN 10 AND 100), account_rollup AS (SELECT a.region, a.tier, r.event_type, count(r.event_id) AS event_count, sum(r.score) AS total_score, avg(r.quality) AS avg_quality, avg(array_length(r.tags)) AS avg_tag_count, max(r.metadata) AS max_metadata FROM ranked_events r JOIN query_dump_accounts a ON r.account_id = a.account_id WHERE r.rn <= 3 GROUP BY a.region, a.tier, r.event_type) SELECT region, tier, event_type, event_count, total_score, avg_quality, avg_tag_count, max_metadata, dense_rank() OVER (PARTITION BY region ORDER BY total_score DESC) AS score_rank FROM account_rollup WHERE event_count > 1;
